<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\ValueObject\UserAccessTemporalCodeRecoveryCodeVO;
use Civi\Lughauth\Shared\Security\SecretDigester;
use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;

#[AllowMockObjectsWithoutExpectations]
final class UserAccessTemporalCodeRecoveryCodeVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = 'hmac-sha256:p1:cypher';
        $ref = UserAccessTemporalCodeRecoveryCodeVO::from($value);
        $this->assertEquals('****er', $ref->value());
        $other = UserAccessTemporalCodeRecoveryCodeVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = UserAccessTemporalCodeRecoveryCodeVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = UserAccessTemporalCodeRecoveryCodeVO::tryFrom(1, $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(UserAccessTemporalCodeRecoveryCodeVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = UserAccessTemporalCodeRecoveryCodeVO::from('hmac-sha256:p1:cypher');
        $same = UserAccessTemporalCodeRecoveryCodeVO::from('hmac-sha256:p1:cypher');
        $other = UserAccessTemporalCodeRecoveryCodeVO::from('hmac-sha256:p1:ocyphered');
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
    public function test_empty(): void
    {
        $ref = UserAccessTemporalCodeRecoveryCodeVO::empty();
        $this->assertNull($ref->value());
    }
    public function test_try_from_empty(): void
    {
        $ref = UserAccessTemporalCodeRecoveryCodeVO::tryFrom(null, new ConstraintFailList());
        $this->assertNull($ref->value());
    }
    public function test_stored_builders(): void
    {
        $this->assertEquals('hmac-sha256:p1:cypher', UserAccessTemporalCodeRecoveryCodeVO::fromStoredText('hmac-sha256:p1:cypher')->storedValue());
        $this->assertNull(UserAccessTemporalCodeRecoveryCodeVO::fromStoredText(null)->value());
    }
    public function test_plain_builders_digest_the_value(): void
    {
        $digester = $this->createMock(SecretDigester::class);
        $digester->expects($this->exactly(3))->method('digest')->with('gold')->willReturn('hmac-sha256:p1:cypher');
        $errors = new ConstraintFailList();
        $this->assertEquals('hmac-sha256:p1:cypher', UserAccessTemporalCodeRecoveryCodeVO::fromPlainText($digester, 'gold')->storedValue());
        $this->assertEquals('hmac-sha256:p1:cypher', UserAccessTemporalCodeRecoveryCodeVO::tryFromPlainText($digester, 'gold', $errors)?->storedValue());
        $this->assertEquals('hmac-sha256:p1:cypher', UserAccessTemporalCodeRecoveryCodeVO::digestOf($digester, 'gold'));
        $this->assertTrue($errors->isEmpty());
    }
    public function test_verify_and_rehash_delegate_on_digester(): void
    {
        $digester = $this->createMock(SecretDigester::class);
        $digester->expects($this->once())->method('verify')->with('gold', 'hmac-sha256:p1:cypher')->willReturn(true);
        $digester->expects($this->once())->method('needsRehash')->with('hmac-sha256:p1:cypher')->willReturn(false);
        $value = UserAccessTemporalCodeRecoveryCodeVO::from('hmac-sha256:p1:cypher');
        $this->assertTrue($value->verify($digester, 'gold'));
        $this->assertFalse($value->needsRehash($digester));
    }
    public function test_undigested_build_has_error(): void
    {
        $this->expectException(\InvalidArgumentException::class);
        UserAccessTemporalCodeRecoveryCodeVO::from('none');
    }
    public function test_exception_on_wrong_value_1(): void
    {
        $digester = $this->createMock(SecretDigester::class);
        $digester->expects($this->never())->method('digest');
        $this->expectException(ConstraintException::class);
        UserAccessTemporalCodeRecoveryCodeVO::fromPlainText($digester, 'Lorem ipsum dolor sit amet, consectetur adipiscing elit. Vivamus in consectetur purus, sit amet rutrum mi. Vestibulum finibus velit ac ligula feugiat, fermentum mattis justo pretium. Nullam blandit nibh nec tortor ultricies, sit amet pretium tellus ullamcorper. Nulla eu bibendum quam, sed vestibulum est. Nunc vitae imperdiet turpis, vel maximus massa. Mauris vel egestas odio. Sed malesuada a lorem non rhoncus. In sagittis scelerisque risus nec consectetur. In est neque, efficitur ut blandit ut, accumsan vitae sem.');
    }
}
